const KEY='scenario-meijin-v1', uid=()=>crypto.randomUUID(), today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date());
const initial={version:1,title:'',author:'',date:today(),draft:1,font:'Noto Serif JP',size:14,printSize:12,direction:'vertical',dark:false,rate:300,actionSeconds:5,cover:true,chapters:[{id:uid(),title:'新しい章',status:'未着手',text:''}]};
