function type(s){return ScriptFormatting.inferred(s)}
function markup(s){return s.split(/([A-Za-z0-9]+|-+|[０-９！？]+|[…⋯]+)/).map(m=>/^[A-Za-z0-9]{1,2}$/.test(m)?'<span class="tcy">'+esc(m)+'</span>':/^-+$/.test(m)?'<span class="verticalDash">'+esc(m)+'</span>':/^[０-９！？]+$/.test(m)?'<span class="verticalGlyph">'+esc(m)+'</span>':/^[…⋯]+$/.test(m)?'<span class="verticalEllipsis">'+esc(m)+'</span>':esc(m)).join('')}
