function renderText(){const ed=$('#editor'), byLine=new Map(chapter().cuts.map(c=>[c.line,c]));ed.replaceChildren(...chapter().text.split('\n').map((line,i)=>{const p=paragraph(line,ScriptModel.paragraphKind(chapter(),i),chapter().formatOrigins?.[i]);if(byLine.has(i)){p.className='cut';p.dataset.cutId=byLine.get(i).id;p.hidden=p.dataset.cutId!==chapter().pendingCutId&&!ScriptModel.realCuts(chapter()).some(c=>c.line===i);p.contentEditable='false'}return p}));if(ed.lastChild?.dataset.cutId){const p=paragraph('',chapter().placeholderFormat);p.dataset.placeholder='true';ed.append(p)}syncEmpty();selectedRange=null;}
