function download(content,ext,mime='text/plain;charset=utf-8'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type:mime}));a.href=u;a.download=(state.title.replace(/[\\/:*?"<>|]/g,'_')||'脚本')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function exportText(md){let s=(md?'# ':'')+state.title+'\n\n'+[state.author,state.date,`第${state.draft}稿`].filter(Boolean).join(' / ')+'\n\n';return s+state.chapters.map((c,i)=>(md?'## ':'')+`${i+1}. ${c.title}\n\n`+printableText(c)).join('\n\n'+(md?'---\n\n':'────────────────\n\n'))}
$('#export').onclick=()=>{modal('作品を書き出す',`<button class="exportoption" id="outPdf">PDFに保存<small>A4 横・縦書き・ページ番号付き</small></button><button class="exportoption" id="outPrint">印刷</button><label><input id="coverField" type="checkbox" ${state.cover?'checked':''}> 表紙を付ける</label><button class="exportoption" id="outTxt">テキスト .txt<small>柱・ト書き・セリフを保ったプレーンテキスト</small></button><button class="exportoption" id="outMd">Markdown .md<small>章見出し付きの汎用テキスト</small></button><p>PDFは直接保存します（高解像度画像のため文字検索はできません）。TXT / MDには内部カットIDを含みません。</p>`);$('#outTxt').onclick=()=>download('\uFEFF'+exportText(false),'txt');$('#outMd').onclick=()=>download(exportText(true),'md','text/markdown;charset=utf-8');const output=async pdf=>{state.cover=$('#coverField').checked;recordHistory();save();$('#dialog').close();try{await printProject(pdf)}catch(e){console.error(e);toast(e.message?.startsWith('選択したフォント')?e.message:'PDFを生成できませんでした。原稿を保存して再試行してください。')}};$('#outPrint').onclick=()=>{state.cover=$('#coverField').checked;recordHistory();save();$('#dialog').close();openPrintPreview()};$('#outPdf').onclick=()=>output(true)};
function printableText(c){const real=new Set(ScriptModel.realCuts(c).map(x=>x.line)),all=new Set(c.cuts.map(x=>x.line));return c.text.split('\n').filter((s,i)=>!all.has(i)||real.has(i)).join('\n')}
// Builds the A4 pages in #printRoot and returns the page count (cover included).
async function layoutPrint(){const loadedFont=await document.fonts.load(`400 ${state.printSize}pt "${state.font}"`,state.chapters.map(c=>c.text).join(''));if(!loadedFont.length)throw Error('選択したフォントを読み込めません。通信を確認してください。');await document.fonts.load(`400 28pt "${state.font}"`,state.title+state.author+state.date+'第'+state.draft+'稿');await document.fonts.ready;const root=$('#printRoot');root.replaceChildren();document.documentElement.style.setProperty('--printsize',state.printSize+'pt');let number=0;
if(state.cover){const cover=document.createElement('section');cover.className='printpage cover';cover.innerHTML=`<h1>${esc(state.title)}</h1><p>${esc(state.author)}<br>${esc(state.date)}<br>第${esc(state.draft)}稿</p>`;root.append(cover);const previous=root.className;root.classList.add('pdf-render');const heading=cover.querySelector('h1');for(let size=28;size>12&&cover.scrollHeight>cover.clientHeight+1;size--)heading.style.fontSize=(size-1)+'pt';root.className=previous}
// Two columns stack an upper and a lower tier on each page; chapters then continue in the next tier.
const columns=state.printColumns===2?2:1,measure=document.createElement('div');measure.style.cssText=`position:fixed;left:-10000px;top:0;width:257mm;height:${columns===2?81:170}mm;writing-mode:vertical-rl;font-family:'${state.font}',serif;font-size:${state.printSize}pt;line-height:1.9;white-space:pre-wrap;line-break:strict;overflow-wrap:break-word;visibility:hidden;`;document.body.append(measure);let tiers=[],titles=[];
function page(){if(!tiers.length)return;number++;const page=document.createElement('section');page.className='printpage';if(columns===2){const wrap=document.createElement('div');wrap.className='printtiers';wrap.append(...tiers);page.append(wrap)}else page.append(tiers[0]);const foot=document.createElement('div');foot.className='printfoot';foot.innerHTML=`<span>${esc(state.title)}</span><span>${esc(titles.join(' / '))}</span><span>${number}</span>`;page.append(foot);root.append(page);tiers=[];titles=[]}
function emit(c){if(!measure.childNodes.length)return;const body=document.createElement('div');body.className='printbody'+(columns===2?' tier':'');body.innerHTML=measure.innerHTML;tiers.push(body);if(!titles.includes(c.title))titles.push(c.title);measure.replaceChildren();if(tiers.length===columns)page()}
for(const c of state.chapters){if(!ScriptModel.realCuts(c).length)continue;for(const [lineIndex,line] of c.text.split('\n').entries()){if(c.cuts.some(x=>x.line===lineIndex)&&!ScriptModel.realCuts(c).some(x=>x.line===lineIndex))continue;const kind=ScriptModel.paragraphKind(c,lineIndex);let p=paragraph(line,kind);const boundary=c.cuts.find(x=>x.line===lineIndex);if(boundary){p.dataset.cutId=boundary.id;p.className='cut';p.style.paddingInlineStart='0';p.style.textIndent='0'}p.style.margin='0 0 0 .6em';measure.append(p);if(measure.scrollWidth>measure.clientWidth+2){p.remove();emit(c);measure.append(p);if(measure.scrollWidth>measure.clientWidth+2){p.remove();let chunk='';for(const char of Array.from(line)){p=paragraph(chunk+char,kind);p.style.margin='0 0 0 .6em';measure.replaceChildren(p);if(measure.scrollWidth>measure.clientWidth+2&&chunk){measure.replaceChildren(paragraph(chunk,kind));emit(c);chunk=char}else chunk+=char}measure.replaceChildren(paragraph(chunk,kind))}}}emit(c)}page();measure.remove();return root.children.length}
async function printProject(pdf=false){toast('印刷用のページを組んでいます…');await layoutPrint();if(pdf)await downloadPdf();else window.print()}
// A clean older tab must not overwrite a manuscript saved by another window.
window.addEventListener('pagehide',()=>{if(dirty)save()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&dirty)save()});window.addEventListener('beforeunload',e=>{if(dirty){save();if(dirty){e.preventDefault();e.returnValue=''}}});window.addEventListener('storage',e=>{if(e.key===KEY)toast('別のタブで更新がありました。同時編集を避け、バックアップを取ってください。')});

$('#editor').addEventListener('wheel',e=>{if(state.direction==='vertical'&&Math.abs(e.deltaY)>Math.abs(e.deltaX)){e.preventDefault();$('#editor').scrollLeft-=e.deltaY}},{passive:false});
$('#deleteChapter').onclick=()=>{const c=chapter();modal('章を削除','<p>'+esc(c.title)+'を削除します。この画面を閉じるとキャンセルします。削除後は「元に戻す」で取り消せます（再読み込みまで）。</p><label><input type="checkbox" id="deleteBackup"> バックアップを保存する</label><button class="primary" id="confirmDelete">削除する</button>');$('#confirmDelete').onclick=()=>{if($('#deleteBackup').checked)download(JSON.stringify(state,null,2),'json','application/json');state.chapters=state.chapters.filter(x=>x.id!==c.id);if(!state.chapters.length)state.chapters.push(ScriptModel.migrateChapter({id:uid(),title:'新しい章',text:'',status:'未着手'}));active=state.chapters[0].id;ScriptModel.renumber(state);recordHistory();save();render();$('#dialog').close()}};
let selectedRange;document.addEventListener('selectionchange',()=>{const sel=window.getSelection();if(sel.rangeCount&&!sel.isCollapsed&&$('#editor').contains(sel.anchorNode)&&$('#editor').contains(sel.focusNode))selectedRange=sel.getRangeAt(0).cloneRange()});
$('#splitChapter').onmousedown=e=>e.preventDefault();$('#splitChapter').onclick=()=>{if(!selectedRange||!selectedRange.toString().trim()||!$('#editor').contains(selectedRange.commonAncestorContainer))return toast('本文を選択してください');const range=selectedRange.cloneRange(),source=chapter();modal('選択範囲から章を作成','<label>章のタイトル</label><input id="splitTitle" value="新しい章"><button id="confirmSplit" class="primary">選択範囲を移動</button>');$('#confirmSplit').onclick=()=>{if(source!==chapter())return;const records=rangeRecords(range,true);assignLines(source,domLines($('#editor')));const c={id:uid(),title:$('#splitTitle').value||'新しい章',text:'',status:'未着手'};assignLines(c,records);state.chapters.splice(state.chapters.indexOf(source)+1,0,c);active=c.id;selectedRange=null;ScriptModel.renumber(state);recordHistory();save();render();$('#dialog').close()}};

window.addEventListener('manuscriptstoragechange',()=>toast('別の画面で原稿が更新されました。同時編集を避け、JSONを保存してください。'));
